#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;
struct Case { float r,g,b,f; string ref; };
vector<Case> C;

struct V { int L,S,SD,H,Q,QD,P,T,B1,B3,TH,CL; };

static inline float fl(double x){ return (float)x; }

static inline float hue2(int B1,int B3,int TH,float p,float q,float t){
  if(t<0.0f) t+=1.0f; if(t>1.0f) t-=1.0f;
  bool c1,c2,c3;
  if(TH==0){ c1 = t<1.0f/6.0f; c2 = t<0.5f; c3 = t<2.0f/3.0f; }
  else     { c1 = (double)t<1.0/6.0; c2=(double)t<0.5; c3=(double)t<2.0/3.0; }
  if(c1){ switch(B1){
      case 0: return p+(q-p)*6.0f*t;
      case 1: return p+(q-p)*(6.0f*t);
      case 2: return fl((double)p+((double)q-(double)p)*6.0*(double)t);
      case 3: return p+6.0f*(q-p)*t;
      default:return p+(q-p)*t*6.0f; } }
  if(c2) return q;
  if(c3){ switch(B3){
      case 0: return p+(q-p)*(2.0f/3.0f-t)*6.0f;
      case 1: return fl((double)p+((double)q-(double)p)*(2.0/3.0-(double)t)*6.0);
      case 2: return p+(q-p)*6.0f*(2.0f/3.0f-t);
      case 3: return p+(q-p)*(0.666667f-t)*6.0f;
      default:return p+(q-p)*fl(2.0/3.0-(double)t)*6.0f; } }
  return p;
}

static inline void eval(const V&v,float r,float g,float b,float fac,float&or_,float&og,float&ob){
  float mx=max(r,max(g,b)), mn=min(r,min(g,b));
  float l = (v.L==0)? (mx+mn)/2.0f : fl((((double)mx)+(double)mn)/2.0);
  float s=0.0f,h=0.0f;
  if(mx!=mn){
    float d=mx-mn;
    bool big = (v.SD==0)? (l>0.5f) : !(l<0.5f);
    switch(v.S){
      case 0: s = big? d/(2.0f-mx-mn) : d/(mx+mn); break;
      case 1: s = fl( big? (double)d/(2.0-(double)mx-(double)mn) : (double)d/((double)mx+(double)mn) ); break;
      case 2: s = big? d/(2.0f-(mx+mn)) : d/(mx+mn); break;
      default: s = d/(1.0f-fabsf(2.0f*l-1.0f)); break;
    }
    switch(v.H){
      case 0: h = (mx==r)? (g-b)/d+(g<b?6.0f:0.0f) : (mx==g)? (b-r)/d+2.0f : (r-g)/d+4.0f; h/=6.0f; break;
      case 1: { double dh = (mx==r)? ((double)g-(double)b)/(double)d+(g<b?6.0:0.0) : (mx==g)? ((double)b-(double)r)/(double)d+2.0 : ((double)r-(double)g)/(double)d+4.0; h=fl(dh/6.0); } break;
      case 2: h = (mx==r)? (g-b)/d+(g<b?6.0f:0.0f) : (mx==g)? (b-r)/d+2.0f : (r-g)/d+4.0f; h=fl((double)h/6.0); break;
      case 3: h = (mx==r)? (g-b)/d+(g<b?6.0f:0.0f) : (mx==g)? (b-r)/d+2.0f : (r-g)/d+4.0f; h=h*(1.0f/6.0f); break;
      default:{ float n = (mx==r)? (g-b)/d+(g<b?6.0f:0.0f) : (mx==g)? (b-r)/d+2.0f : (r-g)/d+4.0f; h=n*60.0f/360.0f; } break;
    }
