  float sf = (v.CL==0)? s*fac : fl((double)s*(double)fac);
  if(sf<0.0f) sf=0.0f; if(sf>1.0f) sf=1.0f;
  s=sf;
  float q,p;
  bool lo = (v.QD==0)? (l<0.5f) : !(l>0.5f);
  switch(v.Q){
    case 0: q = lo? l*(1.0f+s) : l+s-l*s; break;
    case 1: q = fl( lo? (double)l*(1.0+(double)s) : (double)l+(double)s-(double)l*(double)s ); break;
    case 2: q = lo? l+l*s : l+s-l*s; break;
    default: q = lo? l*(1.0f+s) : (l+s)-l*s; break;
  }
  switch(v.P){ case 0: p=2.0f*l-q; break; case 1: p=fl(2.0*(double)l-(double)q); break; default: p=l+l-q; break; }
