    default: t1=h+0.333333f; t3=h-0.333333f; break;
  }
  or_=hue2(v.B1,v.B3,v.TH,p,q,t1);
  og =hue2(v.B1,v.B3,v.TH,p,q,h);
  ob =hue2(v.B1,v.B3,v.TH,p,q,t3);
